1	import { unprocessable } from "../errors.js";
2	
3	export async function assertEnvironmentSelectionForCompany(
4	  environmentsSvc: {
5	    getById(environmentId: string): Promise<{
6	      id: string;
7	      companyId: string;
8	      driver: string;
9	      status?: string | null;
10	      config: Record<string, unknown> | null;
11	    } | null>;
12	  },
13	  companyId: string,
14	  environmentId: string | null | undefined,
15	  options?: {
16	    allowedDrivers?: string[];
17	    allowedSandboxProviders?: string[];
18	  },
19	) {
20	  if (environmentId === undefined || environmentId === null) return;
21	  const environment = await environmentsSvc.getById(environmentId);
22	  if (!environment || environment.companyId !== companyId) {
23	    throw unprocessable("Environment not found.");
24	  }
25	  if (environment.status === "archived") {
26	    throw unprocessable("Environment is archived.");
27	  }
28	  if (options?.allowedDrivers && !options.allowedDrivers.includes(environment.driver)) {
29	    throw unprocessable(
30	      `Environment driver "${environment.driver}" is not allowed here. Allowed drivers: ${options.allowedDrivers.join(", ")}`,
31	    );
32	  }
33	  if (environment.driver === "sandbox") {
34	    const config = environment.config && typeof environment.config === "object"
35	      ? environment.config as Record<string, unknown>
36	      : {};
37	    const provider = typeof config.provider === "string" ? config.provider : "";
38	    if (provider === "fake") {
39	      throw unprocessable(
40	        `Environment sandbox provider "${provider}" is not allowed here. The built-in fake provider is probe-only and cannot execute runs.`,
41	      );
42	    }
43	    if (
44	      options?.allowedSandboxProviders
45	      && options.allowedSandboxProviders.length > 0
46	      && !options.allowedSandboxProviders.includes(provider)
47	    ) {
48	      throw unprocessable(
49	        `Environment sandbox provider "${provider || "unknown"}" is not allowed here. Allowed providers: ${options.allowedSandboxProviders.join(", ")}`,
50	      );
51	    }
52	  }
53	}
